      out.write("                const loc = urlParams.get('location_id') || urlParams.get('location') || '';\r\n");
      out.write("                const mode = urlParams.get('work_type') || urlParams.get('work_mode') || '';\r\n");
      out.write("                const sort = urlParams.get('sort') || 'newest';\r\n");
      out.write("                const page = parseInt(urlParams.get('page')) || 1;\r\n");
      out.write("\r\n");
      out.write("                if (keywordInput && q) keywordInput.value = q;\r\n");
      out.write("                if (deptSelect && dept) deptSelect.value = dept;\r\n");
      out.write("                if (locationSelect && loc) locationSelect.value = loc;\r\n");
      out.write("                if (workTypeSelect && mode) workTypeSelect.value = mode;\r\n");
      out.write("                if (sortSelect && sort) sortSelect.value = sort;\r\n");
      out.write("                currentPage = page;\r\n");
      out.write("\r\n");
      out.write("                toggleClearButton();\r\n");
      out.write("                renderFilterChips();\r\n");
      out.write("\r\n");
      out.write("                // Nếu URL có query parameters khác ban đầu thì gọi AJAX để đồng bộ\r\n");
      out.write("                if (q || dept || loc || mode || (sort && sort !== 'newest') || page > 1) {\r\n");
      out.write("                    loadJobsFromApi(false);\r\n");
      out.write("                }\r\n");
      out.write("            }\r\n");
      out.write("\r\n");
      out.write("            // 2. Đồng bộ State lên URL Query Parameters (KN-224)\r\n");
      out.write("            function syncStateToUrl(pushToHistory = true) {\r\n");
      out.write("                const params = new URLSearchParams();\r\n");
      out.write("                const q = keywordInput.value.trim();\r\n");
      out.write("                const dept = deptSelect.value;\r\n");
      out.write("                const loc = locationSelect.value;\r\n");
      out.write("                const mode = workTypeSelect.value;\r\n");
      out.write("                const sort = sortSelect.value;\r\n");
      out.write("\r\n");
      out.write("                if (q) params.set('q', q);\r\n");
      out.write("                if (dept) params.set('department_id', dept);\r\n");
      out.write("                if (loc) params.set('location_id', loc);\r\n");
      out.write("                if (mode) params.set('work_type', mode);\r\n");
      out.write("                if (sort && sort !== 'newest') params.set('sort', sort);\r\n");
      out.write("                if (currentPage > 1) params.set('page', currentPage);\r\n");
      out.write("\r\n");
      out.write("                const newUrl = window.location.pathname + (params.toString() ? '?' + params.toString() : '');\r\n");
      out.write("                if (pushToHistory) {\r\n");
      out.write("                    window.history.pushState({ path: newUrl }, '', newUrl);\r\n");
      out.write("                } else {\r\n");
      out.write("                    window.history.replaceState({ path: newUrl }, '', newUrl);\r\n");
      out.write("                }\r\n");
      out.write("            }\r\n");
      out.write("\r\n");
      out.write("            // 3. Hiển thị nút xóa nhanh từ khóa tìm kiếm\r\n");
      out.write("            function toggleClearButton() {\r\n");
      out.write("                if (keywordClearBtn) {\r\n");
      out.write("                    keywordClearBtn.style.display = keywordInput.value.trim() ? 'block' : 'none';\r\n");
      out.write("                }\r\n");
      out.write("            }\r\n");
      out.write("\r\n");
      out.write("            // 4. Render Active Filter Chips (KN-224)\r\n");
      out.write("            function renderFilterChips() {\r\n");
      out.write("                chipsContainer.innerHTML = '';\r\n");
      out.write("                let hasFilters = false;\r\n");
      out.write("\r\n");
      out.write("                const q = keywordInput.value.trim();\r\n");
      out.write("                if (q) {\r\n");
      out.write("                    hasFilters = true;\r\n");
      out.write("                    chipsContainer.appendChild(createChip('Từ khóa: ' + q, () => {\r\n");
      out.write("                        keywordInput.value = '';\r\n");
      out.write("                        toggleClearButton();\r\n");
      out.write("                        applyFilters(1);\r\n");
      out.write("                    }));\r\n");
      out.write("                }\r\n");
      out.write("\r\n");
      out.write("                if (deptSelect.value) {\r\n");
      out.write("                    hasFilters = true;\r\n");
      out.write("                    const text = deptSelect.options[deptSelect.selectedIndex].text;\r\n");
      out.write("                    chipsContainer.appendChild(createChip('Phòng ban: ' + text, () => {\r\n");
      out.write("                        deptSelect.value = '';\r\n");
      out.write("                        applyFilters(1);\r\n");
      out.write("                    }));\r\n");
      out.write("                }\r\n");
      out.write("\r\n");
      out.write("                if (locationSelect.value) {\r\n");
      out.write("                    hasFilters = true;\r\n");
      out.write("                    const text = locationSelect.options[locationSelect.selectedIndex].text;\r\n");
      out.write("                    chipsContainer.appendChild(createChip('Địa điểm: ' + text, () => {\r\n");
      out.write("                        locationSelect.value = '';\r\n");
      out.write("                        applyFilters(1);\r\n");
      out.write("                    }));\r\n");
      out.write("                }\r\n");
      out.write("\r\n");
      out.write("                if (workTypeSelect.value) {\r\n");
      out.write("                    hasFilters = true;\r\n");
      out.write("                    const text = workTypeSelect.options[workTypeSelect.selectedIndex].text;\r\n");
      out.write("                    chipsContainer.appendChild(createChip('Hình thức: ' + text, () => {\r\n");
      out.write("                        workTypeSelect.value = '';\r\n");
      out.write("                        applyFilters(1);\r\n");
      out.write("                    }));\r\n");
      out.write("                }\r\n");
      out.write("\r\n");
      out.write("                activeFilterChips.style.display = hasFilters ? 'flex' : 'none';\r\n");
      out.write("            }\r\n");
      out.write("\r\n");
      out.write("            function createChip(label, onRemove) {\r\n");
      out.write("                const chip = document.createElement('span');\r\n");
      out.write("                chip.className = 'filter-chip';\r\n");
      out.write("                chip.innerHTML = label + ' <i class=\"bi bi-x chip-remove\"></i>';\r\n");
      out.write("                chip.querySelector('.chip-remove').addEventListener('click', onRemove);\r\n");
      out.write("                return chip;\r\n");
      out.write("            }\r\n");
      out.write("\r\n");
      out.write("            // 5. Gọi API lấy danh sách việc làm công khai (KN-219, KN-222, KN-223)\r\n");
      out.write("            window.loadJobsFromApi = function(pushHistory = true) {\r\n");
      out.write("                // UI: Hiển thị Skeleton loading, ẩn các state khác\r\n");
      out.write("                loadingState.style.display = 'block';\r\n");
      out.write("                jobCardsGrid.style.display = 'none';\r\n");
      out.write("                emptyState.style.display = 'none';\r\n");
      out.write("                errorState.style.display = 'none';\r\n");
      out.write("                paginationNav.style.display = 'none';\r\n");
      out.write("\r\n");
      out.write("                syncStateToUrl(pushHistory);\r\n");
      out.write("                renderFilterChips();\r\n");
      out.write("\r\n");
      out.write("                const q = keywordInput.value.trim();\r\n");
      out.write("                const dept = deptSelect.value;\r\n");
      out.write("                const loc = locationSelect.value;\r\n");
      out.write("                const mode = workTypeSelect.value;\r\n");
      out.write("                const sort = sortSelect.value;\r\n");
      out.write("\r\n");
      out.write("                const apiUrl = contextPath + '/api/v1/public/jobs?' + new URLSearchParams({\r\n");
      out.write("                    q: q,\r\n");
      out.write("                    department_id: dept,\r\n");
      out.write("                    location_id: loc,\r\n");
      out.write("                    work_type: mode,\r\n");
      out.write("                    sort: sort,\r\n");
      out.write("                    page: currentPage,\r\n");
      out.write("                    limit: pageSize\r\n");
      out.write("                }).toString();\r\n");
      out.write("\r\n");
      out.write("                fetch(apiUrl, {\r\n");
      out.write("                    method: 'GET',\r\n");
      out.write("                    headers: { 'Accept': 'application/json' }\r\n");
      out.write("                })\r\n");
      out.write("                .then(res => {\r\n");
      out.write("                    if (!res.ok) throw new Error('Mã phản hồi lỗi: ' + res.status);\r\n");
      out.write("                    return res.json();\r\n");
      out.write("                })\r\n");
      out.write("                .then(json => {\r\n");
      out.write("                    loadingState.style.display = 'none';\r\n");
      out.write("                    if (!json.success || !json.data) {\r\n");
      out.write("                        showError(json.error || 'Dữ liệu không hợp lệ từ máy chủ.');\r\n");
      out.write("                        return;\r\n");
      out.write("                    }\r\n");
      out.write("\r\n");
      out.write("                    const jobs = json.data;\r\n");
      out.write("                    const pagination = json.pagination;\r\n");
      out.write("\r\n");
      out.write("                    // Cập nhật số lượng\r\n");
      out.write("                    totalBadge.textContent = pagination.total || 0;\r\n");
      out.write("                    resultsSubtext.textContent = 'Tìm thấy ' + (pagination.total || 0) + ' vị trí việc làm đang mở tuyển';\r\n");
      out.write("\r\n");
      out.write("                    if (jobs.length === 0) {\r\n");
      out.write("                        jobCardsGrid.innerHTML = '';\r\n");
      out.write("                        emptyState.style.display = 'block';\r\n");
      out.write("                        paginationNav.style.display = 'none';\r\n");
      out.write("                        return;\r\n");
      out.write("                    }\r\n");
      out.write("\r\n");
      out.write("                    // Render danh sách Card công việc\r\n");
      out.write("                    renderJobCards(jobs);\r\n");
      out.write("                    jobCardsGrid.style.display = 'flex';\r\n");
      out.write("\r\n");
      out.write("                    // Render Phân trang\r\n");
      out.write("                    renderPagination(pagination);\r\n");
      out.write("                })\r\n");
      out.write("                .catch(err => {\r\n");
      out.write("                    loadingState.style.display = 'none';\r\n");
      out.write("                    showError(err.message || 'Không thể tải dữ liệu.');\r\n");
      out.write("                });\r\n");
      out.write("            };\r\n");
      out.write("\r\n");
      out.write("            // 6. Render Card HTML\r\n");
      out.write("            function renderJobCards(jobs) {\r\n");
      out.write("                let html = '';\r\n");
      out.write("                jobs.forEach(job => {\r\n");
      out.write("                    const reqCode = job.requisitionId ? job.requisitionId.substring(0, 8).toUpperCase() : 'JOB';\r\n");
      out.write("                    const dept = escapeHtml(job.departmentName || 'Toàn công ty');\r\n");
      out.write("                    const loc = escapeHtml(job.location || 'Toàn quốc');\r\n");
      out.write("                    const workType = escapeHtml(job.workType || 'Toàn thời gian');\r\n");
      out.write("                    const salary = escapeHtml(job.formattedSalary || 'Thỏa thuận');\r\n");
      out.write("                    const deadline = escapeHtml(job.formattedDeadline || '--');\r\n");
      out.write("                    const desc = escapeHtml(job.description || 'Vui lòng nhấn xem chi tiết để tìm hiểu thông tin yêu cầu và quyền lợi vị trí tuyển dụng.');\r\n");
      out.write("                    const detailUrl = job.detailUrl || (contextPath + '/careers/job?id=' + (job.requisitionId || job.id));\r\n");
      out.write("\r\n");
      out.write("                    html += `\r\n");
      out.write("                        <div class=\"col-12 col-md-6 col-lg-4\">\r\n");
      out.write("                            <article class=\"job-card\">\r\n");
      out.write("                                <div class=\"d-flex justify-content-between align-items-center mb-2.5\">\r\n");
      out.write("                                    <span class=\"badge bg-light text-secondary border font-monospace px-2 py-1\">\r\n");
      out.write("                                        ${reqCode}\r\n");
      out.write("                                    </span>\r\n");
      out.write("                                    <span class=\"badge bg-success-subtle text-success border border-success-subtle px-2 py-1 text-xs fw-semibold\">\r\n");
      out.write("                                        <i class=\"bi bi-broadcast me-1\"></i>Đang mở tuyển\r\n");
      out.write("                                    </span>\r\n");
      out.write("                                </div>\r\n");
      out.write("                                <h3 class=\"job-title\" title=\"${escapeHtml(job.title)}\">\r\n");
      out.write("                                    <a href=\"${detailUrl}\" class=\"text-decoration-none text-dark\">\r\n");
      out.write("                                        ${escapeHtml(job.title)}\r\n");
      out.write("                                    </a>\r\n");
      out.write("                                </h3>\r\n");
      out.write("                                <div class=\"text-secondary small fw-medium mb-3\">\r\n");
      out.write("                                    <i class=\"bi bi-building me-1 text-primary\"></i> \r\n");
      out.write("                                    <span>${dept}</span>\r\n");
      out.write("                                </div>\r\n");
      out.write("                                <div class=\"d-flex flex-wrap gap-1.5 mb-3\">\r\n");
      out.write("                                    <span class=\"badge-pill-soft badge-location\">\r\n");
      out.write("                                        <i class=\"bi bi-geo-alt\"></i> ${loc}\r\n");
      out.write("                                    </span>\r\n");
      out.write("                                    <span class=\"badge-pill-soft badge-mode\">\r\n");
      out.write("                                        <i class=\"bi bi-laptop\"></i> ${workType}\r\n");
      out.write("                                    </span>\r\n");
      out.write("                                    <span class=\"badge-pill-soft badge-salary\">\r\n");
      out.write("                                        <i class=\"bi bi-cash-stack\"></i> ${salary}\r\n");
      out.write("                                    </span>\r\n");
      out.write("                                </div>\r\n");
      out.write("                                <div class=\"job-desc-clamp mb-4 flex-grow-1\">\r\n");
      out.write("                                    ${desc}\r\n");
      out.write("                                </div>\r\n");
      out.write("                                <div class=\"pt-3 border-top d-flex justify-content-between align-items-center mt-auto\">\r\n");
      out.write("                                    <div class=\"small\">\r\n");
      out.write("                                        <span class=\"text-muted d-block text-xs\">Hạn nhận hồ sơ:</span>\r\n");
      out.write("                                        <span class=\"fw-semibold text-dark text-xs\">\r\n");
      out.write("                                            <i class=\"bi bi-calendar3 me-1 text-secondary\"></i> ${deadline}\r\n");
      out.write("                                        </span>\r\n");
      out.write("                                    </div>\r\n");
      out.write("                                    <a href=\"${detailUrl}#applyCardContainer\" class=\"btn btn-outline-primary btn-sm px-3 rounded-pill fw-semibold\">\r\n");
      out.write("                                        Ứng tuyển <i class=\"bi bi-arrow-right ms-1\"></i>\r\n");
      out.write("                                    </a>\r\n");
      out.write("                                </div>\r\n");
      out.write("                            </article>\r\n");
      out.write("                        </div>\r\n");
      out.write("                    `;\r\n");
      out.write("                });\r\n");
      out.write("                jobCardsGrid.innerHTML = html;\r\n");
      out.write("            }\r\n");
      out.write("\r\n");
      out.write("            // 7. Render Pagination Buttons (KN-221)\r\n");
      out.write("            function renderPagination(pagination) {\r\n");
      out.write("                const totalPages = pagination.totalPages || 1;\r\n");
      out.write("                const page = pagination.page || 1;\r\n");
      out.write("\r\n");
      out.write("                if (totalPages <= 1) {\r\n");
      out.write("                    paginationNav.style.display = 'none';\r\n");
      out.write("                    return;\r\n");
      out.write("                }\r\n");
      out.write("\r\n");
      out.write("                paginationNav.style.display = 'flex';\r\n");
      out.write("                let html = '';\r\n");
      out.write("\r\n");
      out.write("                // Nút Trước\r\n");
      out.write("                html += `\r\n");
      out.write("                    <li class=\"page-item ${page <= 1 ? 'disabled' : ''}\">\r\n");
      out.write("                        <a class=\"page-link\" href=\"javascript:void(0)\" onclick=\"applyFilters(${page - 1})\">\r\n");
      out.write("                            <i class=\"bi bi-chevron-left\"></i> Trước\r\n");
      out.write("                        </a>\r\n");
      out.write("                    </li>\r\n");
      out.write("                `;\r\n");
      out.write("\r\n");
      out.write("                // Số trang logic\r\n");
      out.write("                const start = Math.max(1, page - 2);\r\n");
      out.write("                const end = Math.min(totalPages, page + 2);\r\n");
      out.write("\r\n");
      out.write("                if (start > 1) {\r\n");
      out.write("                    html += `<li class=\"page-item\"><a class=\"page-link\" href=\"javascript:void(0)\" onclick=\"applyFilters(1)\">1</a></li>`;\r\n");
      out.write("                    if (start > 2) {\r\n");
      out.write("                        html += `<li class=\"page-item disabled\"><span class=\"page-link\">...</span></li>`;\r\n");
      out.write("                    }\r\n");
      out.write("                }\r\n");
      out.write("\r\n");
      out.write("                for (let i = start; i <= end; i++) {\r\n");
      out.write("                    html += `\r\n");
      out.write("                        <li class=\"page-item ${i === page ? 'active' : ''}\">\r\n");
      out.write("                            <a class=\"page-link\" href=\"javascript:void(0)\" onclick=\"applyFilters(${i})\">${i}</a>\r\n");
      out.write("                        </li>\r\n");
      out.write("                    `;\r\n");
      out.write("                }\r\n");
      out.write("\r\n");
      out.write("                if (end < totalPages) {\r\n");
      out.write("                    if (end < totalPages - 1) {\r\n");
      out.write("                        html += `<li class=\"page-item disabled\"><span class=\"page-link\">...</span></li>`;\r\n");
      out.write("                    }\r\n");
      out.write("                    html += `<li class=\"page-item\"><a class=\"page-link\" href=\"javascript:void(0)\" onclick=\"applyFilters(${totalPages})\">${totalPages}</a></li>`;\r\n");
      out.write("                }\r\n");
      out.write("\r\n");
      out.write("                // Nút Sau\r\n");
      out.write("                html += `\r\n");
      out.write("                    <li class=\"page-item ${page >= totalPages ? 'disabled' : ''}\">\r\n");
      out.write("                        <a class=\"page-link\" href=\"javascript:void(0)\" onclick=\"applyFilters(${page + 1})\">\r\n");
      out.write("                            Sau <i class=\"bi bi-chevron-right\"></i>\r\n");
      out.write("                        </a>\r\n");
      out.write("                    </li>\r\n");
      out.write("                `;\r\n");
      out.write("\r\n");
      out.write("                paginationUl.innerHTML = html;\r\n");
      out.write("            }\r\n");
      out.write("\r\n");
      out.write("            function showError(msg) {\r\n");
      out.write("                errorState.style.display = 'block';\r\n");
      out.write("                errorMessageText.textContent = msg;\r\n");
      out.write("                jobCardsGrid.style.display = 'none';\r\n");
      out.write("                emptyState.style.display = 'none';\r\n");
      out.write("                paginationNav.style.display = 'none';\r\n");
      out.write("            }\r\n");
      out.write("\r\n");
      out.write("            function escapeHtml(str) {\r\n");
      out.write("                if (!str) return '';\r\n");
      out.write("                return String(str)\r\n");
      out.write("                    .replace(/&/g, '&amp;')\r\n");
      out.write("                    .replace(/</g, '&lt;')\r\n");
      out.write("                    .replace(/>/g, '&gt;')\r\n");
      out.write("                    .replace(/\"/g, '&quot;')\r\n");
      out.write("                    .replace(/'/g, '&#039;');\r\n");
      out.write("            }\r\n");
      out.write("\r\n");
      out.write("            // 8. Áp dụng bộ lọc (KN-224)\r\n");
      out.write("            window.applyFilters = function(targetPage = 1) {\r\n");
      out.write("                currentPage = targetPage;\r\n");
      out.write("                loadJobsFromApi(true);\r\n");
      out.write("\r\n");
      out.write("                // Cuộn mượt lên vị trí kết quả nếu đang ở dưới\r\n");
      out.write("                const headerRect = document.getElementById('resultsSubtext').getBoundingClientRect();\r\n");
      out.write("                if (headerRect.top < 0) {\r\n");
      out.write("                    window.scrollTo({\r\n");
      out.write("                        top: window.scrollY + headerRect.top - 120,\r\n");
      out.write("                        behavior: 'smooth'\r\n");
      out.write("                    });\r\n");
      out.write("                }\r\n");
      out.write("            };\r\n");
      out.write("\r\n");
      out.write("            // 9. Xóa toàn bộ bộ lọc\r\n");
      out.write("            window.resetAllFilters = function() {\r\n");
      out.write("                keywordInput.value = '';\r\n");
      out.write("                deptSelect.value = '';\r\n");
      out.write("                locationSelect.value = '';\r\n");
      out.write("                workTypeSelect.value = '';\r\n");
      out.write("                sortSelect.value = 'newest';\r\n");
      out.write("                toggleClearButton();\r\n");
      out.write("                applyFilters(1);\r\n");
      out.write("            };\r\n");
      out.write("\r\n");
      out.write("            // 10. Lắng nghe sự kiện (Debounce trên ô tìm kiếm, Dropdowns change) (KN-224)\r\n");
      out.write("            // Debounce 350ms cho ô tìm kiếm\r\n");
      out.write("            keywordInput.addEventListener('input', function() {\r\n");
      out.write("                toggleClearButton();\r\n");
      out.write("                clearTimeout(debounceTimer);\r\n");
      out.write("                debounceTimer = setTimeout(() => {\r\n");
      out.write("                    applyFilters(1);\r\n");
      out.write("                }, 350);\r\n");
      out.write("            });\r\n");
      out.write("\r\n");
      out.write("            keywordClearBtn.addEventListener('click', function() {\r\n");
      out.write("                keywordInput.value = '';\r\n");
      out.write("                toggleClearButton();\r\n");
      out.write("                applyFilters(1);\r\n");
      out.write("            });\r\n");
      out.write("\r\n");
      out.write("            deptSelect.addEventListener('change', () => applyFilters(1));\r\n");
      out.write("            locationSelect.addEventListener('change', () => applyFilters(1));\r\n");
      out.write("            workTypeSelect.addEventListener('change', () => applyFilters(1));\r\n");
      out.write("            sortSelect.addEventListener('change', () => applyFilters(1));\r\n");
      out.write("\r\n");
      out.write("            // Hỗ trợ back/forward trên trình duyệt (popstate)\r\n");
      out.write("            window.addEventListener('popstate', function() {\r\n");
